const D = { density: .5, scale: 1, energy: .6, speed: 1, warp: .4, hue: 200, x: .5, y: .5, style: 'gradient-thread', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const BW = Math.max(180, Math.floor(width * 0.5)), BH = Math.max(180, Math.floor(height * 0.5));
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.colorMode(HSB, 360, 100, 100, 100);
  S.g.pixelDensity(1); S.g.strokeCap(ROUND); S.bw = BW; S.bh = BH;
}

// Hilbert path cache — rebuild on order (density) or seed change
const order = Math.max(3, Math.min(6, Math.round(4 + P.density * 2)));
if (S.order !== order || S.seedUsed !== P.seed) {
  S.order = order; S.seedUsed = P.seed;
  const side = 1 << order, total = side * side;
  const hx = new Float32Array(total), hy = new Float32Array(total);
  for (let dd = 0; dd < total; dd++) {
    let rx, ry, t = dd, x = 0, y = 0;
    for (let s = 1; s < side; s *= 2) {
      rx = 1 & (t >> 1);
      ry = 1 & (t ^ rx);
      if (ry === 0) { if (rx === 1) { x = s - 1 - x; y = s - 1 - y; } const tmp = x; x = y; y = tmp; }
      x += s * rx; y += s * ry; t = t >> 2;
    }
    hx[dd] = (x + 0.5) / side - 0.5;
    hy[dd] = (y + 0.5) / side - 0.5;
  }
  S.hx = hx; S.hy = hy; S.total = total; S.side = side;
  S.tx = new Float32Array(total); S.ty = new Float32Array(total);
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(3) * 60; S.rotDir = fr(7) < 0.5 ? -1 : 1; S.wseed = fr(11) * 10;
}

const total = S.total, side = S.side, hxp = S.hx, hyp = S.hy, tx = S.tx, ty = S.ty;
const style = P.style;
const sec = K.section;
const hb = (P.hue + S.hoff + sec * 14) % 360;

// slow rotate + breathe (continuous K.t drift = motion floor, never re-phases)
const breathe = 1 + 0.05 * Math.sin(K.t * 0.35) + K.swell * 0.05;
const fit = (0.34 + P.scale * 0.5) * breathe;
const Rx = BW * fit, Ry = BH * fit;
const cx = BW * 0.5 + (P.x - 0.5) * BW * 0.3;
const cy = BH * 0.5 + (P.y - 0.5) * BH * 0.3;
const rot = S.rotDir * K.t * (0.018 + P.speed * 0.02);
const cosr = Math.cos(rot), sinr = Math.sin(rot);
const warpAmp = P.warp * 0.055;
const wt = K.t * 0.5 + S.wseed;
for (let i = 0; i < total; i++) {
  let nx = hxp[i], ny = hyp[i];
  if (warpAmp > 0.0001) {
    nx += warpAmp * Math.sin(hyp[i] * 6.0 + wt);
    ny += warpAmp * Math.cos(hxp[i] * 6.0 + wt * 1.13);
  }
  const rxp = nx * cosr - ny * sinr;
  const ryp = nx * sinr + ny * cosr;
  tx[i] = cx + rxp * Rx;
  ty[i] = cy + ryp * Ry;
}

// self-drawing comet head sweeping along arclength
const rate = 0.05 + P.speed * 0.06;
const progress = (K.t * rate) % 1;
const tailK = 4.5 - P.energy * 1.5;
const baseB = 0.10 + 0.05 * P.energy;
const expo = 0.55 + P.energy * 0.7 + K.intensity * 0.3 + A.rms * 0.6;
const coreW = Math.max(1.2, ((Rx + Ry) * 0.5 / side) * 0.28);
const glowW = coreW * 3.0;
const glowStyle = (style === 'gradient-thread' || style === 'phosphor' || style === 'gold-circuit');

// ground fill (never near-black; sumi is light paper)
let gh, gs, gb;
if (style === 'sumi') { gh = 38; gs = 12; gb = 90; }
else if (style === 'blueprint') { gh = 212; gs = 68; gb = 20; }
else if (style === 'phosphor') { gh = 140; gs = 45; gb = 5; }
else if (style === 'gold-circuit') { gh = 150; gs = 35; gb = 6; }
else { gh = (hb + 175) % 360; gs = 48; gb = 7; }

const g = S.g;
g.push(); g.noStroke(); g.fill(gh, gs, gb); g.rect(0, 0, BW, BH);
g.strokeCap(ROUND);
if (glowStyle) g.blendMode(ADD);
for (let i = 0; i < total - 1; i++) {
  const f = i / (total - 1);
  let d = progress - f; if (d < 0) d += 1;
  const glow = Math.exp(-d * tailK);
  const x0 = tx[i], y0 = ty[i], x1 = tx[i + 1], y1 = ty[i + 1];
  let h, s, b, a, cw = coreW;
  if (style === 'gradient-thread') {
    h = (hb + f * 300 + 18 * Math.sin(f * 18 + K.t * 0.15)) % 360;
    s = 78 + 18 * glow;
    b = Math.min(100, (baseB + glow * expo) * 100); a = 88;
  } else if (style === 'phosphor') {
    const flick = 0.85 + 0.15 * Math.sin(K.t * 7 + f * 40);
    h = 135; s = 88; b = Math.min(100, (baseB + glow * expo) * flick * 100); a = 86;
  } else if (style === 'blueprint') {
    h = 202; s = 55 - glow * 40; b = Math.min(100, (0.30 + glow * 0.65) * 100); a = 92; cw = coreW * 0.85;
  } else if (style === 'gold-circuit') {
    h = 42 + glow * 6; s = 90 - glow * 45; b = Math.min(100, (baseB + glow * expo) * 100); a = 88;
  } else { // sumi
    const tex = 0.55 + 0.45 * Math.sin(i * 12.9898);
    const darkness = 0.12 + glow * 0.7;
    h = 28; s = 18; b = Math.max(15, 90 - darkness * 70);
    a = (52 + 35 * glow) * tex; cw = coreW * (0.7 + 0.6 * tex);
  }
  if (glowStyle && glow > 0.12) {
    g.strokeWeight(glowW);
    g.stroke(h, s * 0.6, b, 13);
    g.line(x0, y0, x1, y1);
  }
  g.strokeWeight(cw);
  g.stroke(h, s, b, a);
  g.line(x0, y0, x1, y1);
  if (style === 'gold-circuit' && glow > 0.35) {
    g.noStroke(); g.fill(48, 55, 100, glow * 85);
    g.rect(x0 - cw, y0 - cw, cw * 2, cw * 2);
  }
}
if (glowStyle) g.blendMode(BLEND);
g.pop();

// composite (tint for VJ alpha compositing)
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio bloom at the drawing head (on top of clk baseline; partial, never full-frame)
const hi = Math.min(total - 1, Math.floor(progress * total));
const hxc = tx[hi] / BW * width, hyc = ty[hi] / BH * height;
const pr = (A.bass * 0.6 + A.treble * 0.3 + K.pulse * 0.35) * (0.4 + P.energy);
if (pr > 0.02) {
  push(); blendMode(ADD); noStroke();
  fill((hb + 30) % 360, 55, 100, 22 * Math.min(1, pr));
  ellipse(hxc, hyc, u * 0.12 * (0.5 + pr));
  blendMode(BLEND); pop();
}
